# Iterating over a list
fruits = ['apple', 'banana', 'cherry']
for fruit in fruits:
    print(fruit)

# Using range()
for i in range(5):
    print(i)  # 0, 1, 2, 3, 4

# Iterating over a string
for char in 'hello':
    print(char)

for i in range(10):
    if i == 5:
        break
    print(i)  # Prints 0, 1, 2, 3, 4

for i in range(5):
    if i == 2:
        continue
    print(i)  # Prints 0, 1, 3, 4
